/*! motion.min.js — Animaciones elegantes y sobrias para informes offline.
    Mejora progresiva: sin JS todo se ve completo. Respeta prefers-reduced-motion
    y no anima contenido que esté oculto al imprimir. Solo transform/opacity.
    También mantiene el estado de lectura (barra de progreso y sección activa
    del índice), que es navegación y por eso corre incluso con reduced-motion. */
(function () {
  'use strict';
  var doc = document,
    html = doc.documentElement,
    reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  html.classList.add('js');

  // Red de seguridad: el HTML autorado debe marcar los SVG, pero si se olvida
  // un icono decorativo no debe quedar anunciado al lector de pantalla.
  var decorative = doc.querySelectorAll('svg.icon,[data-water]');
  for (var s = 0; s < decorative.length; s++) {
    var el = decorative[s];
    if (el.getAttribute('role') !== 'img' && !el.hasAttribute('aria-label') &&
        !el.hasAttribute('aria-labelledby') && !el.querySelector('title')) {
      el.setAttribute('aria-hidden', 'true');
      el.setAttribute('focusable', 'false');
    }
  }

  // Mantiene la barra del navegador y color-scheme alineados con el tema.
  var themeMeta = doc.getElementById('theme-color'),
    schemeMeta = doc.getElementById('color-scheme-meta'),
    lightTheme = themeMeta ? themeMeta.getAttribute('content') || '' : '';
  function syncTheme() {
    var dark = html.getAttribute('data-theme') === 'dark';
    if (themeMeta) themeMeta.setAttribute('content', dark ? '#0f172a' : lightTheme);
    if (schemeMeta) schemeMeta.setAttribute('content', dark ? 'dark' : 'light');
  }
  syncTheme();
  if ((themeMeta || schemeMeta) && window.MutationObserver) {
    new MutationObserver(syncTheme).observe(html, { attributes: true, attributeFilter: ['data-theme'] });
  }

  // Estado de lectura: barra de progreso + sección activa del índice.
  //
  // NO es animación, es navegación: va ANTES del corte de prefers-reduced-motion
  // y funciona igual con el sistema pidiendo menos movimiento. Si el informe no
  // trae barra o no trae índice, el bloque no hace nada (no-op seguro).
  (function readingState() {
    var barFill = doc.querySelector('.read-progress i');
    var links = [].slice.call(doc.querySelectorAll('.toc a[href^="#"]'));
    var targets = [];
    for (var t = 0; t < links.length; t++) {
      var anchor = (links[t].getAttribute('href') || '').slice(1);
      var el = anchor && doc.getElementById(anchor);
      if (el) targets.push({ link: links[t], el: el });
    }
    if (!barFill && !targets.length) return;

    var topbarPx = 0;
    function update() {
      pending = false;
      var y = window.pageYOffset || doc.documentElement.scrollTop;
      var docTop = doc.documentElement;
      if (barFill) {
        var travel = docTop.scrollHeight - window.innerHeight;
        barFill.style.setProperty('--p', travel > 0 ? Math.min(1, Math.max(0, y / travel)) : 1);
      }
      if (!targets.length) return;
      if (!topbarPx) topbarPx = parseFloat(getComputedStyle(html).getPropertyValue('--topbar-h')) || 72;
      // La sección activa es la última cuyo inicio ya ha pasado la línea de
      // lectura, que va por debajo del topbar sticky.
      var line = y + topbarPx + 24;
      var current = 0;
      for (var s = 0; s < targets.length; s++) {
        if (targets[s].el.offsetTop <= line) current = s;
      }
      // Al final del documento manda el último ítem aunque su sección sea corta:
      // si no, una sección final de dos líneas no llegaría a activarse nunca.
      if (y + window.innerHeight >= docTop.scrollHeight - 2) current = targets.length - 1;
      for (var k = 0; k < targets.length; k++) {
        if (k === current) targets[k].link.setAttribute('aria-current', 'true');
        else targets[k].link.removeAttribute('aria-current');
      }
    }
    var pending = false;
    function schedule() {
      if (pending) return;
      pending = true;
      requestAnimationFrame(update);
    }
    window.addEventListener('scroll', schedule, { passive: true });
    window.addEventListener('resize', schedule, { passive: true });
    // Abrir el informe en un ancla (#seccion), recargar con la posicion de
    // scroll restaurada o volver desde la cache del navegador deja la pagina ya
    // desplazada y sin evento de scroll que lo anuncie. Estos tres casos pasan
    // por el estado de lectura de forma SINCRONA: colgarlo de un frame que
    // puede no llegar dejaria la barra en cero y el indice sin marcar.
    window.addEventListener('load', update);
    window.addEventListener('hashchange', update);
    window.addEventListener('pageshow', update);
    update();
  })();

  if (reduced) { html.classList.add('no-anim'); return; }

  var TARGETS = '[data-reveal],[data-slide],[data-grow],[data-draw],[data-pop],[data-count],[data-water],[data-hero],[data-rule]';

  function stagger() {
    var roots = doc.querySelectorAll('[data-stagger]');
    for (var r = 0; r < roots.length; r++) {
      var kids = roots[r].querySelectorAll('[data-reveal],[data-slide],[data-grow],[data-pop],[data-count],[data-water],[data-hero],[data-rule]');
      for (var k = 0; k < kids.length; k++) {
        // Un `--d` escrito a mano gana: la portada encadena con 0/60/120/180ms
        // y el tope del stagger (80ms) se quedaría corto para ese momento.
        if (!kids[k].style.getPropertyValue('--d')) {
          kids[k].style.setProperty('--d', Math.min(k * 20, 80) + 'ms');
        }
      }
    }
  }

  function prepDraw() {
    var els = doc.querySelectorAll('[data-draw]');
    for (var i = 0; i < els.length; i++) {
      try { els[i].style.setProperty('--len', els[i].getTotalLength()); }
      catch (e) { els[i].style.setProperty('--len', 1200); }
    }
  }

  function fmt(n, dec, suffix) {
    var nf = new Intl.NumberFormat('es-ES', { minimumFractionDigits: dec, maximumFractionDigits: dec });
    return nf.format(n) + (suffix || '');
  }

  // cubic-bezier(0.23, 1, 0.32, 1): aceleración corta y deceleración larga.
  function ease(p) {
    var lo = 0, hi = 1, t = p, u, x;
    for (var n = 0; n < 10; n++) {
      u = 1 - t;
      x = 3 * u * u * t * 0.23 + 3 * u * t * t * 0.32 + t * t * t;
      if (x < p) lo = t; else hi = t;
      t = (lo + hi) / 2;
    }
    u = 1 - t;
    return 3 * u * u * t + 3 * u * t * t + t * t * t;
  }

  function counter(el) {
    var raw = parseFloat(el.getAttribute('data-to') || el.textContent.replace(/[^\d.,-]/g, '').replace(/\./g, '').replace(',', '.') || '0');
    var dec = parseInt(el.getAttribute('data-dec') || '0', 10);
    var suffix = el.getAttribute('data-suffix') || '';
    var requested = parseInt(el.getAttribute('data-dur') || '240', 10);
    var dur = isNaN(requested) ? 240 : Math.max(0, Math.min(requested, 280));
    var start = null;
    function step(ts) {
      if (start === null) start = ts;
      var p = dur ? Math.min(1, (ts - start) / dur) : 1;
      el.textContent = fmt(raw * ease(p), dec, suffix);
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function activate(el) {
    el.classList.add('in');
    if (el.hasAttribute('data-count')) counter(el);
  }

  function revealAll() {
    var els = doc.querySelectorAll(TARGETS);
    for (var i = 0; i < els.length; i++) activate(els[i]);
  }

  stagger();
  prepDraw();

  if (!('IntersectionObserver' in window)) { revealAll(); return; }

  var io = new IntersectionObserver(function (entries) {
    for (var i = 0; i < entries.length; i++) {
      if (entries[i].isIntersecting) {
        activate(entries[i].target);
        io.unobserve(entries[i].target);
      }
    }
  }, { threshold: 0.1, rootMargin: '0px 0px -30px 0px' });

  var targets = doc.querySelectorAll(TARGETS);
  for (var t = 0; t < targets.length; t++) io.observe(targets[t]);
})();